import { BlockId, BLOCK_INFO, RaycastHit } from './types';
import { mulberry32 } from './math';

export const WORLD_X = 64;
export const WORLD_Y = 32;
export const WORLD_Z = 64;
export const CHUNK_SIZE = 16;
export const CHUNKS_X = WORLD_X / CHUNK_SIZE;
export const CHUNKS_Z = WORLD_Z / CHUNK_SIZE;
export const WATER_LEVEL = 7;

export class VoxelWorld {
  readonly blocks: Uint8Array;
  readonly dirtyChunks: Set<number> = new Set();

  constructor(seed = 1337) {
    this.blocks = new Uint8Array(WORLD_X * WORLD_Y * WORLD_Z);
    this.generate(seed);
  }

  private index(x: number, y: number, z: number): number {
    return (y * WORLD_Z + z) * WORLD_X + x;
  }

  inBounds(x: number, y: number, z: number): boolean {
    return x >= 0 && x < WORLD_X && y >= 0 && y < WORLD_Y && z >= 0 && z < WORLD_Z;
  }

  getBlock(x: number, y: number, z: number): BlockId {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (!this.inBounds(ix, iy, iz)) {
      return iy < 0 ? BlockId.Bedrock : BlockId.Air;
    }
    return this.blocks[this.index(ix, iy, iz)] as BlockId;
  }

  isSolid(x: number, y: number, z: number): boolean {
    return BLOCK_INFO[this.getBlock(x, y, z)].solid;
  }

  isOpaque(x: number, y: number, z: number): boolean {
    return BLOCK_INFO[this.getBlock(x, y, z)].opaque;
  }

  chunkKey(cx: number, cz: number): number {
    return cz * CHUNKS_X + cx;
  }

  markChunkDirty(cx: number, cz: number): void {
    if (cx >= 0 && cx < CHUNKS_X && cz >= 0 && cz < CHUNKS_Z) {
      this.dirtyChunks.add(this.chunkKey(cx, cz));
    }
  }

  markAllDirty(): void {
    for (let cz = 0; cz < CHUNKS_Z; cz++) {
      for (let cx = 0; cx < CHUNKS_X; cx++) {
        this.dirtyChunks.add(this.chunkKey(cx, cz));
      }
    }
  }

  setBlock(x: number, y: number, z: number, id: BlockId, trackDirty = true): boolean {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (!this.inBounds(ix, iy, iz)) return false;
    const idx = this.index(ix, iy, iz);
    if (this.blocks[idx] === id) return false;
    this.blocks[idx] = id;

    if (trackDirty) {
      const cx = Math.floor(ix / CHUNK_SIZE);
      const cz = Math.floor(iz / CHUNK_SIZE);
      this.markChunkDirty(cx, cz);
      const lx = ix - cx * CHUNK_SIZE;
      const lz = iz - cz * CHUNK_SIZE;
      if (lx === 0) this.markChunkDirty(cx - 1, cz);
      if (lx === CHUNK_SIZE - 1) this.markChunkDirty(cx + 1, cz);
      if (lz === 0) this.markChunkDirty(cx, cz - 1);
      if (lz === CHUNK_SIZE - 1) this.markChunkDirty(cx, cz + 1);
    }
    return true;
  }

  getSurfaceHeight(x: number, z: number): number {
    const ix = Math.max(0, Math.min(WORLD_X - 1, Math.floor(x)));
    const iz = Math.max(0, Math.min(WORLD_Z - 1, Math.floor(z)));
    for (let y = WORLD_Y - 1; y >= 0; y--) {
      if (this.isSolid(ix, y, iz)) return y + 1;
    }
    return 1;
  }

  private generate(seed: number): void {
    const rand = mulberry32(seed);

    // Build smooth value noise grid
    const grid = new Float32Array(17 * 17);
    for (let i = 0; i < grid.length; i++) grid[i] = rand();

    const sampleNoise = (nx: number, nz: number): number => {
      const gx = ((nx % 16) + 16) % 16;
      const gz = ((nz % 16) + 16) % 16;
      const x0 = Math.floor(gx);
      const z0 = Math.floor(gz);
      const fx = gx - x0;
      const fz = gz - z0;
      const sx = fx * fx * (3 - 2 * fx);
      const sz = fz * fz * (3 - 2 * fz);
      const x1 = (x0 + 1) % 16;
      const z1 = (z0 + 1) % 16;
      const v00 = grid[z0 * 17 + x0];
      const v10 = grid[z0 * 17 + x1];
      const v01 = grid[z1 * 17 + x0];
      const v11 = grid[z1 * 17 + x1];
      const a = v00 + (v10 - v00) * sx;
      const b = v01 + (v11 - v01) * sx;
      return a + (b - a) * sz;
    };

    const heightAt = (x: number, z: number): number => {
      const n1 = sampleNoise(x * 0.08, z * 0.08);
      const n2 = sampleNoise(x * 0.18 + 5.2, z * 0.18 + 1.7);
      let h = 10.2 + (n1 - 0.5) * 6.5 + (n2 - 0.5) * 2.2;

      // Flatten central clearing around spawn (32, 32)
      const dx = x - 32;
      const dz = z - 32;
      const distCenter = Math.sqrt(dx * dx + dz * dz);
      if (distCenter < 11) {
        const t = 1 - distCenter / 11;
        h = h * (1 - t) + 10.0 * t;
      }

      // Create scenic shallow pond to the front-right (43, 22)
      const pdx = x - 43;
      const pdz = z - 22;
      const pDist = Math.sqrt(pdx * pdx + pdz * pdz);
      if (pDist < 8.5) {
        const pt = 1 - pDist / 8.5;
        h -= pt * 6.2;
      }

      // Gently raise perimeter hills to frame the valley
      const edgeDist = Math.min(x, z, WORLD_X - 1 - x, WORLD_Z - 1 - z);
      if (edgeDist < 7) {
        h += (7 - edgeDist) * 0.85;
      }

      return Math.max(3, Math.min(WORLD_Y - 10, Math.round(h)));
    };

    // Terrain fill
    for (let z = 0; z < WORLD_Z; z++) {
      for (let x = 0; x < WORLD_X; x++) {
        const h = heightAt(x, z);
        this.setBlock(x, 0, z, BlockId.Bedrock, false);
        for (let y = 1; y <= h; y++) {
          let block = BlockId.Stone;
          if (y === h) {
            if (h <= WATER_LEVEL + 1) {
              block = BlockId.Sand;
            } else if (h >= 15) {
              block = BlockId.Stone;
            } else {
              block = BlockId.Grass;
            }
          } else if (y >= h - 2) {
            block = h <= WATER_LEVEL + 1 ? BlockId.Sand : BlockId.Dirt;
          }
          this.setBlock(x, y, z, block, false);
        }
        // Fill water up to WATER_LEVEL
        for (let y = h + 1; y <= WATER_LEVEL; y++) {
          this.setBlock(x, y, z, BlockId.Water, false);
        }
      }
    }

    // Small starter cobblestone & plank barricade off to the player's left (x=27..29, z=30..31)
    const bx = 27;
    const bz = 29;
    const baseH = this.getSurfaceHeight(bx, bz);
    for (let dx = 0; dx < 3; dx++) {
      this.setBlock(bx + dx, baseH, bz, BlockId.Cobblestone, false);
      this.setBlock(bx + dx, baseH + 1, bz, dx === 1 ? BlockId.Air : BlockId.OakPlanks, false);
    }
    this.setBlock(bx, baseH, bz + 1, BlockId.Cobblestone, false);
    this.setBlock(bx, baseH + 1, bz + 1, BlockId.OakPlanks, false);

    // Place Oak Trees
    const treeSpots: [number, number][] = [
      [18, 22], [22, 16], [14, 34], [20, 46], [36, 48],
      [48, 42], [50, 14], [15, 14], [46, 33], [31, 14],
    ];
    for (const [tx, tz] of treeSpots) {
      const ty = this.getSurfaceHeight(tx, tz);
      if (this.getBlock(tx, ty - 1, tz) !== BlockId.Grass) continue;
      const trunkH = 4 + Math.floor(rand() * 2);
      for (let y = 0; y < trunkH; y++) {
        this.setBlock(tx, ty + y, tz, BlockId.OakLog, false);
      }
      for (let dy = trunkH - 2; dy <= trunkH + 1; dy++) {
        const radius = dy === trunkH + 1 ? 1 : 2;
        for (let dz = -radius; dz <= radius; dz++) {
          for (let dx = -radius; dx <= radius; dx++) {
            if (Math.abs(dx) === radius && Math.abs(dz) === radius && dy >= trunkH) continue;
            if (dx === 0 && dz === 0 && dy < trunkH) continue;
            const px = tx + dx;
            const py = ty + dy;
            const pz = tz + dz;
            if (this.getBlock(px, py, pz) === BlockId.Air) {
              this.setBlock(px, py, pz, BlockId.OakLeaves, false);
            }
          }
        }
      }
    }

    // Place Bamboo Groves (pandas love bamboo!)
    const groveCenters: [number, number][] = [
      [32, 18], [22, 23], [42, 34], [25, 42], [44, 15], [17, 41],
    ];
    for (const [gx, gz] of groveCenters) {
      for (let i = 0; i < 11; i++) {
        const bxPos = gx + Math.floor((rand() - 0.5) * 9);
        const bzPos = gz + Math.floor((rand() - 0.5) * 9);
        if (Math.hypot(bxPos - 32, bzPos - 32) < 6) continue;
        const by = this.getSurfaceHeight(bxPos, bzPos);
        if (this.getBlock(bxPos, by - 1, bzPos) !== BlockId.Grass) continue;
        if (this.getBlock(bxPos, by, bzPos) !== BlockId.Air) continue;
        const stalkH = 3 + Math.floor(rand() * 4);
        for (let y = 0; y < stalkH; y++) {
          this.setBlock(bxPos, by + y, bzPos, BlockId.Bamboo, false);
        }
      }
    }

    this.markAllDirty();
  }

  /**
   * 3D Amanatides & Woo DDA voxel raycast.
   */
  raycast(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, maxDist: number): RaycastHit | null {
    const len = Math.hypot(dx, dy, dz);
    if (len < 1e-8) return null;
    dx /= len;
    dy /= len;
    dz /= len;

    let x = Math.floor(ox);
    let y = Math.floor(oy);
    let z = Math.floor(oz);

    const stepX = dx > 0 ? 1 : dx < 0 ? -1 : 0;
    const stepY = dy > 0 ? 1 : dy < 0 ? -1 : 0;
    const stepZ = dz > 0 ? 1 : dz < 0 ? -1 : 0;

    const tDeltaX = stepX !== 0 ? Math.abs(1 / dx) : Infinity;
    const tDeltaY = stepY !== 0 ? Math.abs(1 / dy) : Infinity;
    const tDeltaZ = stepZ !== 0 ? Math.abs(1 / dz) : Infinity;

    let tMaxX = stepX > 0 ? (x + 1 - ox) * tDeltaX : stepX < 0 ? (ox - x) * tDeltaX : Infinity;
    let tMaxY = stepY > 0 ? (y + 1 - oy) * tDeltaY : stepY < 0 ? (oy - y) * tDeltaY : Infinity;
    let tMaxZ = stepZ > 0 ? (z + 1 - oz) * tDeltaZ : stepZ < 0 ? (oz - z) * tDeltaZ : Infinity;

    let nx = 0;
    let ny = 0;
    let nz = 0;
    let dist = 0;

    for (let i = 0; i < 128; i++) {
      if (dist > maxDist) return null;
      const b = this.getBlock(x, y, z);
      if (b !== BlockId.Air && b !== BlockId.Water) {
        return { x, y, z, nx, ny, nz, dist, block: b };
      }

      if (tMaxX < tMaxY && tMaxX < tMaxZ) {
        dist = tMaxX;
        tMaxX += tDeltaX;
        x += stepX;
        nx = -stepX;
        ny = 0;
        nz = 0;
      } else if (tMaxY < tMaxZ) {
        dist = tMaxY;
        tMaxY += tDeltaY;
        y += stepY;
        nx = 0;
        ny = -stepY;
        nz = 0;
      } else {
        dist = tMaxZ;
        tMaxZ += tDeltaZ;
        z += stepZ;
        nx = 0;
        ny = 0;
        nz = -stepZ;
      }
    }
    return null;
  }
}
