export enum BlockId {
  Air = 0,
  Grass = 1,
  Dirt = 2,
  Stone = 3,
  Cobblestone = 4,
  OakLog = 5,
  OakPlanks = 6,
  OakLeaves = 7,
  Bamboo = 8,
  Sand = 9,
  Water = 10,
  Brick = 11,
  Bedrock = 12,
}

export type ToolKind = 'sword' | 'shield' | 'pickaxe' | 'bow' | 'block';

export interface BlockMeta {
  id: BlockId;
  name: string;
  solid: boolean;
  opaque: boolean;
  transparent: boolean;
  breakable: boolean;
  hardness: number; // seconds with bare hand/non-preferred tool
  pickaxeSpeed: number; // multiplier when using pickaxe
  tiles: { top: number; bottom: number; side: number };
  particleColor: [number, number, number];
  dropSlotBlock: BlockId | null;
}

