import {
  ArrowProjectile,
  BlockId,
  BLOCK_INFO,
  PandaEntity,
  Particle,
  PineappleProjectile,
} from './types';
import { VoxelWorld, WORLD_X, WORLD_Z } from './world';
import { clamp, rayIntersectsAABB } from './math';

export const GRAVITY = 22.0;
export const PINEAPPLE_GRAVITY = 15.0;
export const ARROW_GRAVITY = 11.5;

export interface EntityEvents {
  onPandaThrow: () => void;
  onPandaHurt: () => void;
  onPandaDefeat: (panda: PandaEntity, byReflection: boolean) => void;
  onPineappleHitPlayer: (pineapple: PineappleProjectile) => void;
  onPineappleSplat: (x: number, y: number, z: number) => void;
}

export class EntityManager {
  pandas: PandaEntity[] = [];
  pineapples: PineappleProjectile[] = [];
  arrows: ArrowProjectile[] = [];
  particles: Particle[] = [];

  private nextId = 1;
  private respawnTimer = 0;
  private graceTimer = 1.6;
  readonly targetPandaCount = 6;

  reset(world: VoxelWorld): void {
    this.pandas = [];
    this.pineapples = [];
    this.arrows = [];
    this.particles = [];
    this.respawnTimer = 0;
    this.graceTimer = 1.6;

    // Initial pandas positioned visibly across the bamboo valley & pond ahead of spawn (32.5, y, 35.5)
    const initialSpots: [number, number][] = [
      [32.5, 22.5],
      [25.5, 25.5],
      [39.5, 26.5],
      [29.5, 16.5],
      [38.5, 17.5],
      [21.5, 34.5],
    ];
    for (const [px, pz] of initialSpots) {
      this.spawnPandaAt(world, px, pz);
    }
  }

  spawnPandaAt(world: VoxelWorld, x: number, z: number): PandaEntity {
    const cx = clamp(x, 6, WORLD_X - 6);
    const cz = clamp(z, 6, WORLD_Z - 6);
    const y = world.getSurfaceHeight(cx, cz);
    const p: PandaEntity = {
      id: this.nextId++,
      x: cx,
      y,
      z: cz,
      vx: 0,
      vy: 0,
      vz: 0,
      yaw: Math.random() * Math.PI * 2,
      hp: 100,
      maxHp: 100,
      onGround: true,
      state: 'wander',
      stateTimer: 0.6 + Math.random() * 1.4,
      throwCooldown: 1.5 + Math.random() * 2.4,
      walkPhase: Math.random() * Math.PI * 2,
      hurtTimer: 0,
      wanderYaw: Math.random() * Math.PI * 2,
    };
    this.pandas.push(p);
    return p;
  }

  private spawnPandaAwayFrom(world: VoxelWorld, px: number, pz: number): void {
    const groves: [number, number][] = [
      [32, 16], [20, 22], [44, 34], [24, 45], [46, 16], [16, 42], [48, 28],
    ];
    let best = groves[Math.floor(Math.random() * groves.length)];
    for (let tries = 0; tries < 8; tries++) {
      const cand = groves[Math.floor(Math.random() * groves.length)];
      const gx = cand[0] + (Math.random() - 0.5) * 6;
      const gz = cand[1] + (Math.random() - 0.5) * 6;
      if (Math.hypot(gx - px, gz - pz) >= 13) {
        best = [gx, gz];
        break;
      }
    }
    this.spawnPandaAt(world, best[0], best[1]);
  }

  spawnBlockParticles(x: number, y: number, z: number, blockId: BlockId, count = 12): void {
    const [r, g, b] = BLOCK_INFO[blockId].particleColor;
    for (let i = 0; i < count; i++) {
      this.particles.push({
        x: x + 0.15 + Math.random() * 0.7,
        y: y + 0.15 + Math.random() * 0.7,
        z: z + 0.15 + Math.random() * 0.7,
        vx: (Math.random() - 0.5) * 4.5,
        vy: 1.8 + Math.random() * 3.5,
        vz: (Math.random() - 0.5) * 4.5,
        r: clamp(r + (Math.random() - 0.5) * 0.12, 0, 1),
        g: clamp(g + (Math.random() - 0.5) * 0.12, 0, 1),
        b: clamp(b + (Math.random() - 0.5) * 0.12, 0, 1),
        size: 0.11 + Math.random() * 0.08,
        age: 0,
        maxAge: 0.45 + Math.random() * 0.35,
      });
    }
  }

  spawnBurstParticles(
    x: number,
    y: number,
    z: number,
    palette: [number, number, number][],
    count = 14,
    speed = 5.5
  ): void {
    for (let i = 0; i < count; i++) {
      const col = palette[i % palette.length];
      this.particles.push({
        x: x + (Math.random() - 0.5) * 0.4,
        y: y + (Math.random() - 0.5) * 0.4,
        z: z + (Math.random() - 0.5) * 0.4,
        vx: (Math.random() - 0.5) * speed * 2,
        vy: 1.5 + Math.random() * speed,
        vz: (Math.random() - 0.5) * speed * 2,
        r: col[0],
        g: col[1],
        b: col[2],
        size: 0.12 + Math.random() * 0.09,
        age: 0,
        maxAge: 0.45 + Math.random() * 0.4,
      });
    }
  }

  spawnArrow(x: number, y: number, z: number, dx: number, dy: number, dz: number, speed = 29): void {
    this.arrows.push({
      id: this.nextId++,
      x,
      y,
      z,
      vx: dx * speed,
      vy: dy * speed + 1.4,
      vz: dz * speed,
      age: 0,
    });
  }

  private pandaCollides(world: VoxelWorld, x: number, y: number, z: number): boolean {
    const hw = 0.46;
    const h = 1.42;
    const minX = Math.floor(x - hw);
    const maxX = Math.floor(x + hw);
    const minY = Math.floor(y);
    const maxY = Math.floor(y + h);
    const minZ = Math.floor(z - hw);
    const maxZ = Math.floor(z + hw);
    for (let by = minY; by <= maxY; by++) {
      for (let bz = minZ; bz <= maxZ; bz++) {
        for (let bx = minX; bx <= maxX; bx++) {
          if (world.isSolid(bx, by, bz)) return true;
        }
      }
    }
    return false;
  }

  private movePanda(world: VoxelWorld, p: PandaEntity, dt: number): void {
    p.vy -= GRAVITY * dt;
    // Slight drag on knockback
    const nx = p.x + p.vx * dt;
    if (!this.pandaCollides(world, nx, p.y + 0.05, p.z)) {
      p.x = clamp(nx, 2, WORLD_X - 2);
    } else if (p.onGround && !this.pandaCollides(world, nx, p.y + 1.15, p.z)) {
      p.vy = 7.4; // Hop up 1-block ledge!
      p.onGround = false;
    } else {
      p.vx = 0;
    }

    const nz = p.z + p.vz * dt;
    if (!this.pandaCollides(world, p.x, p.y + 0.05, nz)) {
      p.z = clamp(nz, 2, WORLD_Z - 2);
    } else if (p.onGround && !this.pandaCollides(world, p.x, p.y + 1.15, nz)) {
      p.vy = 7.4;
      p.onGround = false;
    } else {
      p.vz = 0;
    }

    const ny = p.y + p.vy * dt;
    if (!this.pandaCollides(world, p.x, ny, p.z)) {
      p.y = ny;
      p.onGround = false;
    } else {
      if (p.vy < 0) {
        p.y = Math.floor(p.y);
        while (this.pandaCollides(world, p.x, p.y, p.z) && p.y < 30) {
          p.y += 1;
        }
        p.onGround = true;
      }
      p.vy = 0;
    }

    // Float slightly if in water
    if (world.getBlock(p.x, p.y + 0.2, p.z) === BlockId.Water) {
      p.vy = Math.max(p.vy, 2.2);
    }
  }

  private throwPineappleFrom(panda: PandaEntity, targetX: number, targetY: number, targetZ: number): void {
    const startX = panda.x;
    const startY = panda.y + 1.65;
    const startZ = panda.z;

    const jitterX = (Math.random() - 0.5) * 0.9;
    const jitterZ = (Math.random() - 0.5) * 0.9;
    const dx = targetX + jitterX - startX;
    const dy = targetY - startY;
    const dz = targetZ + jitterZ - startZ;
    const horizDist = Math.hypot(dx, dz);

    const flightTime = clamp(horizDist / 12.8, 0.45, 1.45);
    const vx = dx / flightTime;
    const vz = dz / flightTime;
    const vy = (dy + 0.5 * PINEAPPLE_GRAVITY * flightTime * flightTime) / flightTime;

    this.pineapples.push({
      id: this.nextId++,
      x: startX,
      y: startY,
      z: startZ,
      vx,
      vy,
      vz,
      spin: 0,
      age: 0,
      reflected: false,
      ownerPandaId: panda.id,
    });
  }

  damagePanda(
    panda: PandaEntity,
    damage: number,
    knockX: number,
    knockZ: number,
    byReflection: boolean,
    events: EntityEvents
  ): boolean {
    panda.hp -= damage;
    panda.hurtTimer = 0.24;
    panda.vx = knockX;
    panda.vz = knockZ;
    panda.vy = Math.max(panda.vy, 5.2);
    panda.onGround = false;

    if (panda.hp <= 0) {
      this.spawnBurstParticles(
        panda.x,
        panda.y + 0.9,
        panda.z,
        [
          [0.96, 0.96, 0.94],
          [0.16, 0.16, 0.19],
          [0.45, 0.85, 0.3],
          [1.0, 0.85, 0.2],
        ],
        20,
        6.0
      );
      this.pandas = this.pandas.filter((p) => p.id !== panda.id);
      events.onPandaDefeat(panda, byReflection);
      return true;
    } else {
      this.spawnBurstParticles(panda.x, panda.y + 1.0, panda.z, [[0.95, 0.95, 0.95], [0.95, 0.28, 0.24]], 7, 3.8);
      events.onPandaHurt();
      return false;
    }
  }

  /**
   * Checks sword slash / melee hit against incoming pineapples (deflection!) and pandas.
   */
  tryMeleeAttack(
    ox: number,
    oy: number,
    oz: number,
    fx: number,
    fy: number,
    fz: number,
    damage: number,
    canDeflect: boolean,
    events: EntityEvents
  ): { deflectedPineapple: boolean; hitPanda: boolean } {
    let deflectedPineapple = false;

    if (canDeflect) {
      for (const pine of this.pineapples) {
        if (pine.reflected) continue;
        const dx = pine.x - ox;
        const dy = pine.y - oy;
        const dz = pine.z - oz;
        const dist = Math.hypot(dx, dy, dz);
        if (dist <= 4.1) {
          const dot = (dx * fx + dy * fy + dz * fz) / Math.max(0.001, dist);
          if (dot > 0.28 || dist < 1.8) {
            this.reflectPineapple(pine, fx, fy, fz);
            deflectedPineapple = true;
          }
        }
      }
    }

    let hitPanda = false;
    let closestDist = 3.9;
    let bestPanda: PandaEntity | null = null;
    for (const p of this.pandas) {
      const t = rayIntersectsAABB(
        ox,
        oy,
        oz,
        fx,
        fy,
        fz,
        p.x - 0.65,
        p.y,
        p.z - 0.65,
        p.x + 0.65,
        p.y + 1.65,
        p.z + 0.65,
        closestDist
      );
      if (t !== null && t < closestDist) {
        closestDist = t;
        bestPanda = p;
      }
    }

    if (bestPanda) {
      const kLen = Math.hypot(fx, fz) || 1;
      this.damagePanda(bestPanda, damage, (fx / kLen) * 8.5, (fz / kLen) * 8.5, false, events);
      hitPanda = true;
    }

    return { deflectedPineapple, hitPanda };
  }

  reflectPineapple(pine: PineappleProjectile, aimX: number, aimY: number, aimZ: number): void {
    pine.reflected = true;
    pine.age = 0;

    // Auto-assist slightly toward the panda who threw it if roughly in front of aim
    const owner = this.pandas.find((p) => p.id === pine.ownerPandaId);
    let tx = aimX;
    let ty = aimY + 0.14;
    let tz = aimZ;
    if (owner) {
      const odx = owner.x - pine.x;
      const ody = owner.y + 0.9 - pine.y;
      const odz = owner.z - pine.z;
      const olen = Math.hypot(odx, ody, odz) || 1;
      const dot = (odx * aimX + ody * aimY + odz * aimZ) / olen;
      if (dot > 0.35) {
        tx = odx / olen;
        ty = ody / olen + 0.12;
        tz = odz / olen;
      }
    }
    const len = Math.hypot(tx, ty, tz) || 1;
    const speed = 22.0;
    pine.vx = (tx / len) * speed;
    pine.vy = (ty / len) * speed;
    pine.vz = (tz / len) * speed;
    this.spawnBurstParticles(pine.x, pine.y, pine.z, [[1.0, 0.95, 0.45], [1.0, 1.0, 1.0]], 10, 4.5);
  }

  update(
    dt: number,
    world: VoxelWorld,
    playerX: number,
    playerY: number,
    playerZ: number,
    playerAlive: boolean,
    events: EntityEvents
  ): void {
    if (this.graceTimer > 0) this.graceTimer -= dt;

    // Respawn pandas gently up to target count
    if (this.pandas.length < this.targetPandaCount) {
      this.respawnTimer += dt;
      if (this.respawnTimer >= 3.8) {
        this.respawnTimer = 0;
        this.spawnPandaAwayFrom(world, playerX, playerZ);
      }
    }

    // Update Pandas
    for (const p of this.pandas) {
      if (p.hurtTimer > 0) p.hurtTimer = Math.max(0, p.hurtTimer - dt);
      if (p.throwCooldown > 0) p.throwCooldown = Math.max(0, p.throwCooldown - dt);

      const dx = playerX - p.x;
      const dz = playerZ - p.z;
      const dist = Math.hypot(dx, dz);
      const yawToPlayer = Math.atan2(-dx, -dz);

      // Smoothly damp knockback when not actively moving
      if (p.hurtTimer > 0.08) {
        p.vx *= Math.max(0, 1 - dt * 5);
        p.vz *= Math.max(0, 1 - dt * 5);
        this.movePanda(world, p, dt);
        continue;
      }

      if (!playerAlive || dist > 28) {
        p.state = 'wander';
      }

      if (p.state === 'windup') {
        p.yaw = yawToPlayer;
        p.vx *= 0.7;
        p.vz *= 0.7;
        p.stateTimer -= dt;
        if (p.stateTimer <= 0) {
          this.throwPineappleFrom(p, playerX, playerY + 1.1, playerZ);
          events.onPandaThrow();
          p.state = 'cooldown';
          p.stateTimer = 0.7;
          p.throwCooldown = 2.4 + Math.random() * 1.4;
        }
      } else if (p.state === 'cooldown') {
        p.yaw = yawToPlayer;
        p.vx *= 0.8;
        p.vz *= 0.8;
        p.stateTimer -= dt;
        if (p.stateTimer <= 0) {
          p.state = 'chase';
        }
      } else if (playerAlive && dist < 26) {
        p.state = 'chase';
        p.yaw = yawToPlayer;
        const speed = 2.65;
        if (dist > 11.5) {
          p.vx = (dx / dist) * speed;
          p.vz = (dz / dist) * speed;
          p.walkPhase += dt * 7.5;
        } else if (dist < 5.5) {
          // Back up slightly to keep throwing distance
          p.vx = (-dx / dist) * speed * 0.7;
          p.vz = (-dz / dist) * speed * 0.7;
          p.walkPhase += dt * 6;
        } else {
          // Strafe gently around the player
          const strafeSign = p.id % 2 === 0 ? 1 : -1;
          p.vx = (-dz / dist) * speed * 0.55 * strafeSign;
          p.vz = (dx / dist) * speed * 0.55 * strafeSign;
          p.walkPhase += dt * 5;
        }

        if (this.graceTimer <= 0 && p.throwCooldown <= 0 && dist >= 4.2 && dist <= 22) {
          p.state = 'windup';
          p.stateTimer = 0.68; // Clear visual windup telegraph!
        }
      } else {
        // Peaceful bamboo valley wander
        p.stateTimer -= dt;
        if (p.stateTimer <= 0) {
          p.wanderYaw = Math.random() * Math.PI * 2;
          p.stateTimer = 1.6 + Math.random() * 2.5;
        }
        p.yaw = p.wanderYaw;
        p.vx = -Math.sin(p.wanderYaw) * 1.5;
        p.vz = -Math.cos(p.wanderYaw) * 1.5;
        p.walkPhase += dt * 4.5;
      }

      this.movePanda(world, p, dt);
    }

    // Update Pineapples
    const survivingPineapples: PineappleProjectile[] = [];
    for (const pine of this.pineapples) {
      pine.age += dt;
      if (pine.age > 5.0) continue;

      pine.vy -= PINEAPPLE_GRAVITY * dt;
      pine.x += pine.vx * dt;
      pine.y += pine.vy * dt;
      pine.z += pine.vz * dt;
      pine.spin += dt * (pine.reflected ? 16 : 9);

      // Check block hit
      if (world.isSolid(pine.x, pine.y, pine.z)) {
        this.spawnBurstParticles(
          pine.x,
          pine.y,
          pine.z,
          [
            [0.98, 0.82, 0.16],
            [0.9, 0.66, 0.12],
            [0.24, 0.76, 0.2],
          ],
          14,
          5.0
        );
        events.onPineappleSplat(pine.x, pine.y, pine.z);
        continue;
      }

      // Reflected pineapple hitting a panda!
      if (pine.reflected) {
        let hit = false;
        for (const panda of this.pandas) {
          if (
            Math.abs(pine.x - panda.x) < 0.78 &&
            pine.y >= panda.y &&
            pine.y <= panda.y + 1.65 &&
            Math.abs(pine.z - panda.z) < 0.78
          ) {
            const spd = Math.hypot(pine.vx, pine.vz) || 1;
            this.damagePanda(panda, 65, (pine.vx / spd) * 10, (pine.vz / spd) * 10, true, events);
            this.spawnBurstParticles(
              pine.x,
              pine.y,
              pine.z,
              [
                [1.0, 0.88, 0.2],
                [0.35, 0.9, 0.25],
                [1.0, 1.0, 1.0],
              ],
              18,
              6.5
            );
            events.onPineappleSplat(pine.x, pine.y, pine.z);
            hit = true;
            break;
          }
        }
        if (hit) continue;
      } else if (playerAlive) {
        // Check hit against player AABB
        if (
          Math.abs(pine.x - playerX) < 0.62 &&
          pine.y >= playerY &&
          pine.y <= playerY + 1.85 &&
          Math.abs(pine.z - playerZ) < 0.62
        ) {
          events.onPineappleHitPlayer(pine);
          if (pine.reflected) {
            // Player's shield reflected it! Keep it alive flying away
            survivingPineapples.push(pine);
          } else {
            this.spawnBurstParticles(
              pine.x,
              pine.y,
              pine.z,
              [
                [0.98, 0.82, 0.16],
                [0.24, 0.76, 0.2],
              ],
              12,
              4.6
            );
          }
          continue;
        }
      }

      survivingPineapples.push(pine);
    }
    this.pineapples = survivingPineapples;

    // Update Arrows
    const survivingArrows: ArrowProjectile[] = [];
    for (const a of this.arrows) {
      a.age += dt;
      if (a.age > 3.5) continue;
      a.vy -= ARROW_GRAVITY * dt;
      a.x += a.vx * dt;
      a.y += a.vy * dt;
      a.z += a.vz * dt;

      if (world.isSolid(a.x, a.y, a.z)) {
        this.spawnBurstParticles(a.x, a.y, a.z, [[0.72, 0.56, 0.34], [0.85, 0.85, 0.85]], 6, 3.0);
        continue;
      }

      let hitPanda = false;
      for (const panda of this.pandas) {
        if (
          Math.abs(a.x - panda.x) < 0.65 &&
          a.y >= panda.y &&
          a.y <= panda.y + 1.62 &&
          Math.abs(a.z - panda.z) < 0.65
        ) {
          const spd = Math.hypot(a.vx, a.vz) || 1;
          this.damagePanda(panda, 36, (a.vx / spd) * 7.5, (a.vz / spd) * 7.5, false, events);
          hitPanda = true;
          break;
        }
      }
      if (!hitPanda) survivingArrows.push(a);
    }
    this.arrows = survivingArrows;

    // Update Particles
    const survivingParticles: Particle[] = [];
    for (const pt of this.particles) {
      pt.age += dt;
      if (pt.age >= pt.maxAge) continue;
      pt.vy -= 16 * dt;
      pt.x += pt.vx * dt;
      pt.y += pt.vy * dt;
      pt.z += pt.vz * dt;
      survivingParticles.push(pt);
    }
    this.particles = survivingParticles;
  }
}
