import { Vec3 } from './types';

export type Mat4 = Float32Array;

export function createMat4(): Mat4 {
  const m = new Float32Array(16);
  m[0] = 1;
  m[5] = 1;
  m[10] = 1;
  m[15] = 1;
  return m;
}

export function identityMat4(out: Mat4): Mat4 {
  out.fill(0);
  out[0] = 1;
  out[5] = 1;
  out[10] = 1;
  out[15] = 1;
  return out;
}

export function perspectiveMat4(out: Mat4, fovRad: number, aspect: number, near: number, far: number): Mat4 {
  const f = 1.0 / Math.tan(fovRad / 2);
  const nf = 1 / (near - far);
  out.fill(0);
  out[0] = f / aspect;
  out[5] = f;
  out[10] = (far + near) * nf;
  out[11] = -1;
  out[14] = 2 * far * near * nf;
  return out;
}

export function multiplyMat4(out: Mat4, a: Mat4, b: Mat4): Mat4 {
  const r = new Float32Array(16);
  for (let col = 0; col < 4; col++) {
    for (let row = 0; row < 4; row++) {
      r[col * 4 + row] =
        a[0 * 4 + row] * b[col * 4 + 0] +
        a[1 * 4 + row] * b[col * 4 + 1] +
        a[2 * 4 + row] * b[col * 4 + 2] +
        a[3 * 4 + row] * b[col * 4 + 3];
    }
  }
  out.set(r);
  return out;
}

export function translateMat4(out: Mat4, a: Mat4, x: number, y: number, z: number): Mat4 {
  const t = createMat4();
  t[12] = x;
  t[13] = y;
  t[14] = z;
  return multiplyMat4(out, a, t);
}

export function scaleMat4(out: Mat4, a: Mat4, x: number, y: number, z: number): Mat4 {
  const s = createMat4();
  s[0] = x;
  s[5] = y;
  s[10] = z;
  return multiplyMat4(out, a, s);
}

export function rotateXMat4(out: Mat4, a: Mat4, rad: number): Mat4 {
  const r = createMat4();
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  r[5] = c;
  r[6] = s;
  r[9] = -s;
  r[10] = c;
  return multiplyMat4(out, a, r);
}

export function rotateYMat4(out: Mat4, a: Mat4, rad: number): Mat4 {
  const r = createMat4();
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  r[0] = c;
  r[2] = -s;
  r[8] = s;
  r[10] = c;
  return multiplyMat4(out, a, r);
}

export function rotateZMat4(out: Mat4, a: Mat4, rad: number): Mat4 {
  const r = createMat4();
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  r[0] = c;
  r[1] = s;
  r[4] = -s;
  r[5] = c;
  return multiplyMat4(out, a, r);
}

export function cameraViewMat4(out: Mat4, x: number, y: number, z: number, yaw: number, pitch: number): Mat4 {
  identityMat4(out);
  rotateXMat4(out, out, -pitch);
  rotateYMat4(out, out, -yaw);
  translateMat4(out, out, -x, -y, -z);
  return out;
}

export function forwardFromAngles(yaw: number, pitch: number): Vec3 {
  const cp = Math.cos(pitch);
  return {
    x: -Math.sin(yaw) * cp,
    y: Math.sin(pitch),
    z: -Math.cos(yaw) * cp,
  };
}

export function rayIntersectsAABB(
  ox: number,
  oy: number,
  oz: number,
  dx: number,
  dy: number,
  dz: number,
  minX: number,
  minY: number,
  minZ: number,
  maxX: number,
  maxY: number,
  maxZ: number,
  maxDist: number
): number | null {
  let tmin = 0;
  let tmax = maxDist;

  const axes: [number, number, number, number][] = [
    [ox, dx, minX, maxX],
    [oy, dy, minY, maxY],
    [oz, dz, minZ, maxZ],
  ];

  for (const [o, d, lo, hi] of axes) {
    if (Math.abs(d) < 1e-8) {
      if (o < lo || o > hi) return null;
    } else {
      let t1 = (lo - o) / d;
      let t2 = (hi - o) / d;
      if (t1 > t2) {
        const tmp = t1;
        t1 = t2;
        t2 = tmp;
      }
      tmin = Math.max(tmin, t1);
      tmax = Math.min(tmax, t2);
      if (tmin > tmax) return null;
    }
  }
  return tmin >= 0 && tmin <= maxDist ? tmin : null;
}

export function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
